<?php $page_title='Users';require_once __DIR__.'/../includes/header.php';if(!is_admin())die('Admin only');$rows=$pdo->query("SELECT name,email,role,status,created_at FROM users ORDER BY id")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Users</h2><a href="add.php" class="btn btn-primary">+ Add User</a></div><div class="card p-3"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=$u['role']?></td><td><?=$u['status']?></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>